--
-- Table structure for table `points_history`
--

DROP TABLE IF EXISTS `points_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `points_history` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `booking_id` bigint(20) unsigned DEFAULT NULL,
  `tipe` enum('kredit','debit') NOT NULL,
  `jumlah_poin` int(10) unsigned NOT NULL,
  `poin_saldo_after` int(10) unsigned DEFAULT NULL COMMENT 'Snapshot saldo poin pasca transaksi',
  `sumber` varchar(80) NOT NULL COMMENT 'Lihat komentar tabel untuk daftar valid sumber',
  `keterangan` varchar(255) DEFAULT NULL,
  `expired_at` timestamp NULL DEFAULT NULL,
  `is_expired` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Di-flag true oleh cron loyalty:expire-points',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `points_history_booking_id_foreign` (`booking_id`),
  KEY `ph_user_tipe` (`user_id`,`tipe`),
  KEY `ph_user_expiry` (`user_id`,`is_expired`,`expired_at`),
  KEY `ph_expired_at` (`expired_at`),
  KEY `idx_ph_user_created` (`user_id`,`created_at`),
  CONSTRAINT `points_history_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `points_history_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

